    },
    {
      "вещество": "Муцигин (muscigine)",
      "содержание": "следовые количества (< 0,001 % от сухого веса)",
      "влияние": "Агонист ГАМК-рецепторов; усиливает седативное действие мусцимола."
    },
    {
